public class Triangulo implements Calculavel { private final double a,b,c; public Triangulo(double a,double b,double c){if(a<=0||b<=0||c<=0||a+b<=c||a+c<=b||b+c<=a)throw new IllegalArgumentException("Triângulo inválido");this.a=a;this.b=b;this.c=c;} public double calcularArea(){double s=(a+b+c)/2;return Math.sqrt(s*(s-a)*(s-b)*(s-c));} public double calcularPerimetro(){return a+b+c;} public String getNome(){return "Triângulo";} }
